def letter_grades(marks):
    total = 0
    for mark in marks:
        total += mark
    average = total / len(marks)
    letters = []
    for mark in marks:
        if mark > average + 15:
            letters.append("A")
        elif mark < average - 15:
            letters.append("C")
        else:
            letters.append("B")
    return letters

